import{_ as i,l as n,o as e,c as s,v as r,p as l,x as o,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"近似比","description":"","frontmatter":{"title":"近似比","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/approximation-ratio.md","filePath":"cs/approximation-ratio.md","lastUpdated":1789023840000}'),A={name:"cs/approximation-ratio.md"};function c(P,a,E,T,_,m){const t=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="近似比" tabindex="-1">近似比 <a class="header-anchor" href="#近似比" aria-label="Permalink to &quot;近似比&quot;">​</a></h1><div class="epigraph"><p>对最小化，$A(x)/OPT(x)\\le\\rho$；对最大化，$OPT/A\\le\\rho$。$\\rho$ 是算法对一切实例的最坏倍数，不是平均手感。</p><footer>—— 据 CLRS 第 35 章；Garey and Johnson, Computers and Intractability, 1979 整理</footer></div><p>上一课<a href="/cs/sat-3sat">SAT 与 3-SAT</a>把精确可满足钉在 NPC。许多优化版（最小顶点覆盖、度量 TSP）同样难：除非 \\(P=NP\\)，没有多项式最优算法。本课不重做归约。缺口是<strong>带保证的次优</strong>：多项式算法输出可行解，比值有界。后课随机化可以是近似的工具，也可以是精确期望；本课先钉确定性比值。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>顶点覆盖：贪心「反复挑覆盖最多未盖边的点」没有常数比；标准 2-近似是：求极大匹配，两端点都进覆盖——匹配边必须各盖一端，故 \\(|C|\\le 2\\,OPT\\)。度量 TSP：MST 走两遍再捷径，三角不等式给出 2-近似；Christofides 的 \\(3/2\\) 点名不证。缺口是定义 \\(\\rho\\)-近似，不是再解 3-SAT。</p><p>背包有 FPTAS：比值 \\(1+\\varepsilon\\)、时间随 \\(1/\\varepsilon\\) 多项式。本课点名：不是所有 NPC 优化都有 FPTAS；有的连常数比都不存在（在 \\(P\\ne NP\\) 下），那是硬度，本课不启用 PCP。</p><h3 id="比不是「实践中差一倍」" tabindex="-1">比不是「实践中差一倍」 <a class="header-anchor" href="#比不是「实践中差一倍」" aria-label="Permalink to &quot;比不是「实践中差一倍」&quot;">​</a></h3><p>\\(\\rho\\) 必须对所有 \\(x\\) 成立。平均实例更好不算证明。也可写绝对误差，主干用比。随机算法的比可以对期望或高概率，下一课再说硬币；本课默认确定性。</p><p><span class="marginnote">CLRS 第 35 章。Garey/Johnson 已区分「精确完全」与启发式。顶点覆盖 2-近似与匹配的关系用<a href="/cs/bipartite-match">二分图匹配</a>的基数直觉，一般图极大匹配仍多项式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>证明可行（覆盖、回路）。证明 \\(A(x)\\le\\rho\\,OPT(x)\\)：常用对偶、匹配下界、树的权 \\(\\le OPT\\)。给出紧实例说明 \\(\\rho\\) 不能随便改小。</p>',11)),(e(),l(d,null,{default:o(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NPC%5B%22%E7%B2%BE%E7%A1%AE%20NPC%22%5D%20--%3E%20APX%5B%22%E5%A4%9A%E9%A1%B9%E5%BC%8F%20%CF%81-%E8%BF%91%E4%BC%BC%22%5D%0A%20%20APX%20--%3E%20VC%5B%22%E9%A1%B6%E7%82%B9%E8%A6%86%E7%9B%96%EF%BC%9A2%22%5D%0A%20%20APX%20--%3E%20TSP%5B%22%E5%BA%A6%E9%87%8F%20TSP%EF%BC%9A2%22%5D%0A%20%20APX%20--%3E%20NO%5B%22%E6%97%A0%E4%BF%9D%E8%AF%81%E7%9A%84%E8%B4%AA%E5%BF%83%EF%BC%9A%E4%B8%8D%E7%AE%97%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p><a href="/cs/greedy-correct">贪心正确性</a>要的是 \\(\\rho=1\\)。本课允许 \\(\\rho\\gt 1\\)，但仍要证。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>近似把「完全性墙」与「可计算的保证」分开。编译里寄存器着色的启发式通常<strong>没有</strong>本课这种 \\(\\rho\\)；那是工程，不要回标成本课的定理。也不要把 PTAS/FPTAS 的定义写进每一题。</p><p>比值随 \\(n\\) 增长（如 \\(O(\\log n)\\) 集合覆盖）仍是近似保证，只是不是常数。点名即可。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证不可近似性。不写线性规划舍入的一般理论。后课默认：谈到近似，先写 \\(\\rho\\) 与可行。随机化算法的硬币与期望是下一缺口；算法课在随机化之后交给编译。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\rho\\)-近似：多项式、可行、最坏比值 \\(\\le\\rho\\)。</li><li>顶点覆盖 \\(2\\)、度量 TSP \\(2\\) 是标准例子；无证明的贪心不算。</li><li>精确仍 NPC 时，近似是主干出口之一。</li><li>出处：CLRS 第 35 章；Garey and Johnson, 1979。</li></ul>',8))])}const S=i(A,[["render",c]]);export{C as __pageData,S as default};
